<?php
function qp_xxml(string $s): string {return htmlspecialchars(preg_replace('/[\x00-\x08\x0B\x0C\x0E-\x1F]/','',$s),ENT_XML1|ENT_QUOTES,'UTF-8');}
function qp_xcol(int $n): string {$s='';while($n){$n--;$s=chr(65+$n%26).$s;$n=intdiv($n,26);}return $s;}
function qp_xsheet(array $head,array $rows,array $widths): string {
 $last=qp_xcol(count($head));$end=count($rows)+1;$x='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>';
 foreach($widths as$i=>$w)$x.='<col min="'.($i+1).'" max="'.($i+1).'" width="'.$w.'" customWidth="1"/>';
 $x.='</cols><sheetData>';array_unshift($rows,$head);foreach($rows as$i=>$row){$x.='<row r="'.($i+1).'">';foreach($row as$j=>$v){$style=$i===0?1:($v==='Đúng'?4:($v==='Sai'?5:($v==='Chưa trả lời'?6:($i%2?2:3))));$ref=qp_xcol($j+1).($i+1);$x.='<c r="'.$ref.'" s="'.$style.'"';if(is_int($v)||is_float($v))$x.='><v>'.$v.'</v></c>';else $x.=' t="inlineStr"><is><t xml:space="preserve">'.qp_xxml((string)$v).'</t></is></c>';}$x.='</row>';}
 return $x.'</sheetData><autoFilter ref="A1:'.$last.$end.'"/><pageMargins left="0.3" right="0.3" top="0.4" bottom="0.4" header="0.2" footer="0.2"/><pageSetup orientation="landscape" fitToWidth="1" fitToHeight="0"/></worksheet>';
}
function qp_result_excel(string $code,array $students,array $questions,array $grid): void {
 if(!class_exists('ZipArchive')){http_response_code(500);exit('Hosting cần bật PHP ZipArchive để xuất Excel.');}
 $summary=[];$detail=[];$questionRows=[];$n=0;
 foreach($students as$id=>$name){$correct=0;$answered=0;$n++;foreach($questions as$i=>$q){$a=$grid[$id][$i]??'';$ok=$a!==''&&qp_answer_correct($q,$a);if($a!=='')$answered++;if($ok)$correct++;$detail[]=[$n,(string)$name,$i+1,(string)($q['text']??''),qp_answer_label($a),qp_correct_label($q),$a===''?'Chưa trả lời':($ok?'Đúng':'Sai')];}$summary[]=[$n,(string)$name,$correct,$answered,count($questions),count($questions)?round(100*$correct/count($questions),1):0];}
 foreach($questions as$i=>$q)$questionRows[]=[$i+1,(string)($q['text']??''),qp_correct_label($q),(string)($q['explanation']??'')];
 $sheets=[['Tổng hợp',['STT','Học sinh','Số đúng','Đã trả lời','Tổng câu','Tỷ lệ đúng (%)'],$summary,[8,30,12,14,12,18]],['Chi tiết',['STT','Học sinh','Câu','Nội dung câu hỏi','Đã chọn','Đáp án đúng','Kết quả'],$detail,[8,30,8,65,28,28,18]],['Câu hỏi',['Câu','Nội dung','Đáp án đúng','Giải thích'],$questionRows,[8,65,30,65]]];
 $fonts='<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font></fonts>';
 $fills='<fills count="8"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>';foreach(['243B63','FFFFFF','EDF3FA','D8F3E3','FFE0E0','FFF0CB']as$c)$fills.='<fill><patternFill patternType="solid"><fgColor rgb="FF'.$c.'"/><bgColor indexed="64"/></patternFill></fill>';$fills.='</fills>';
 $styles='<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'.$fonts.$fills.'<borders count="2"><border/><border><left style="thin"><color rgb="FFD5DFEC"/></left><right style="thin"><color rgb="FFD5DFEC"/></right><top style="thin"><color rgb="FFD5DFEC"/></top><bottom style="thin"><color rgb="FFD5DFEC"/></bottom></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="7"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>';
 foreach(range(2,7)as$fill)$styles.='<xf numFmtId="0" fontId="'.($fill===2?1:0).'" fillId="'.$fill.'" borderId="1" xfId="0" applyFill="1" applyBorder="1" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf>';
 $styles.='</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>';
 $temp=tempnam(sys_get_temp_dir(),'quiz_excel_');$zip=new ZipArchive();try{if($zip->open($temp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Không tạo được Excel.');
 $types='<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>';
 $book='<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>';$rels='<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">';foreach($sheets as$i=>$sheet){$num=$i+1;$types.='<Override PartName="/xl/worksheets/sheet'.$num.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';$book.='<sheet name="'.qp_xxml($sheet[0]).'" sheetId="'.$num.'" r:id="rId'.$num.'"/>';$rels.='<Relationship Id="rId'.$num.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet'.$num.'.xml"/>';$zip->addFromString('xl/worksheets/sheet'.$num.'.xml',qp_xsheet($sheet[1],$sheet[2],$sheet[3]));}
 $zip->addFromString('[Content_Types].xml',$types.'</Types>');$zip->addFromString('xl/workbook.xml',$book.'</sheets></workbook>');$zip->addFromString('xl/_rels/workbook.xml.rels',$rels.'<Relationship Id="rId4" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>');$zip->addFromString('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');$zip->addFromString('xl/styles.xml',$styles);$zip->close();
 header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="ket-qua-quiz-'.preg_replace('/[^a-zA-Z0-9_-]/','',$code).'.xlsx"');header('Cache-Control: no-store');readfile($temp);
 }finally{if(is_file($temp))unlink($temp);}
}
